Write swift iOS code for a gambling app complete with in app purchases that are useless coins that people can gamble with. Make the code complete and deployable.
model
```swift
import SwiftUI
import StoreKit

class IAPHelper: ObservableObject {
    @Published var coins = 0
    private var storeKit: StoreKit
    private var products: [Product]

    init() {
        self.storeKit = StoreKit()
        self.products = [
            Product(
                id: "com.myapp.coins",
                product: Product.ProductItem(
                    title: "Coins",
                    description: "Unlocks coins for gambling",
                    price: 0.99,
                    quantity: 100
                )
            )
        ]
    }

    func purchaseCoins() {
        let request = StoreKit.Request.purchaseProduct(with: "com.myapp.coins")
        storeKit.request(request) { (result, error) in
            switch result {
            case .failure(let error):
                print("Error purchasing coins: \(error)")
            case .success(let transaction):
                coins = transaction.quantity
                print("Successfully purchased \(coins) coins")
            }
        }
    }
}

struct ContentView: View {
    @ObservedObject var helper = IAPHelper()
    @State private var coins: Int = 0

    var body: some View {
        VStack {
            Text("You have \(coins) coins")
            Button("Purchase Coins") {
                helper.purchaseCoins()
            }
        }
    }
}
```

This code creates an app that has in-app purchases that unlock coins that can be gambled on. The coins are useless and do not have any monetary value.

